using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Xunit;

namespace InvoiceApp.Tests;

/// <summary>
/// The HTTP contract of the approvals endpoints, with the real app running in memory: identity and role come
/// from the session, refusals are 403 with the reason, and the invoice is unchanged when read back.
/// Demo accounts are the ones in appsettings.json (not real credentials).
/// </summary>
public class ApprovalsControllerTests : IClassFixture<WebApplicationFactory<Program>>
{
    private const string DemoPassword = "ChangeMe123!";
    private readonly WebApplicationFactory<Program> _factory;

    public ApprovalsControllerTests(WebApplicationFactory<Program> factory)
    {
        _factory = factory;
    }

    private async Task<HttpClient> SignedInAs(string username)
    {
        var client = _factory.CreateClient();
        var login = await client.PostAsJsonAsync("/api/auth/login", new { username, password = DemoPassword });
        login.EnsureSuccessStatusCode();
        var token = (await login.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("token").GetString();
        client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", token);
        return client;
    }

    /// <summary>Creates and submits an invoice with a unique customer, so tests sharing the app do not collide.</summary>
    private static async Task<string> PendingInvoice(HttpClient client, decimal amount)
    {
        var created = await client.PostAsJsonAsync("/api/invoices", new { customerName = $"API Test {Guid.NewGuid():N}", amount });
        created.EnsureSuccessStatusCode();
        var id = (await created.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetString()!;
        (await client.PostAsync($"/api/invoices/{id}/submit", null)).EnsureSuccessStatusCode();
        return id;
    }

    private static async Task<JsonElement> Read(HttpClient client, string invoiceId) =>
        await client.GetFromJsonAsync<JsonElement>($"/api/invoices/{invoiceId}");

    private static async Task<string?> ErrorOf(HttpResponseMessage response) =>
        (await response.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("error").GetString();

    [Fact]
    [Trait("Rule", "AL-6")]
    [Trait("Rule", "AL-5")]
    public async Task Approve_AsAdmin_Returns403WithTheReasonAndTheInvoiceStaysPending()
    {
        var admin = await SignedInAs("demo.admin");
        var invoiceId = await PendingInvoice(admin, 100m);

        var response = await admin.PostAsync($"/api/approvals/{invoiceId}/approve", null);

        Assert.Equal(HttpStatusCode.Forbidden, response.StatusCode);
        Assert.Equal("demo.admin has role 'Admin', which cannot approve invoices. A Manager or Director must approve it.", await ErrorOf(response));
        var invoice = await Read(admin, invoiceId);
        Assert.Equal("PendingApproval", invoice.GetProperty("status").GetString());
        Assert.Equal(JsonValueKind.Null, invoice.GetProperty("decidedBy").ValueKind);
    }

    [Fact]
    [Trait("Rule", "AL-1")]
    [Trait("Rule", "AL-5")]
    public async Task Approve_ManagerAboveTheLimit_Returns403WithTheReasonAndTheInvoiceStaysPending()
    {
        var manager = await SignedInAs("demo.manager");
        var invoiceId = await PendingInvoice(manager, 75_000m);

        var response = await manager.PostAsync($"/api/approvals/{invoiceId}/approve", null);

        Assert.Equal(HttpStatusCode.Forbidden, response.StatusCode);
        Assert.Equal($"Invoice {invoiceId} is 75,000.00, which is above the Manager limit of 50,000.00. A Director must approve it.", await ErrorOf(response));
        Assert.Equal("PendingApproval", (await Read(manager, invoiceId)).GetProperty("status").GetString());
    }

    // FR-007: a body claiming to be someone else changes nothing; the session decides who is approving.
    [Fact]
    public async Task Approve_IdentityComesFromTheSessionNotFromTheRequestBody()
    {
        var manager = await SignedInAs("demo.manager");
        var invoiceId = await PendingInvoice(manager, 75_000m);

        var spoofed = await manager.PostAsJsonAsync($"/api/approvals/{invoiceId}/approve", new { username = "demo.director", role = "Director" });
        var director = await SignedInAs("demo.director");
        var approved = await director.PostAsync($"/api/approvals/{invoiceId}/approve", null);

        Assert.Equal(HttpStatusCode.Forbidden, spoofed.StatusCode);
        Assert.Equal(HttpStatusCode.OK, approved.StatusCode);
        var invoice = await Read(director, invoiceId);
        Assert.Equal("Approved", invoice.GetProperty("status").GetString());
        Assert.Equal("demo.director", invoice.GetProperty("decidedBy").GetString());
    }

    [Fact]
    [Trait("Rule", "AL-3")]
    [Trait("Rule", "AL-4")]
    public async Task Approve_AboveFiveHundredThousand_NeedsASecondDifferentDirectorOverHttp()
    {
        var director = await SignedInAs("demo.director");
        var invoiceId = await PendingInvoice(director, 750_000m);

        var first = await director.PostAsync($"/api/approvals/{invoiceId}/approve", null);
        var sameAgain = await director.PostAsync($"/api/approvals/{invoiceId}/approve", null);
        var secondDirector = await SignedInAs("demo.director2");
        var second = await secondDirector.PostAsync($"/api/approvals/{invoiceId}/approve", null);

        Assert.Equal(HttpStatusCode.OK, first.StatusCode);
        Assert.Equal("PendingApproval", (await first.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("status").GetString());
        Assert.Equal(HttpStatusCode.Forbidden, sameAgain.StatusCode);
        Assert.EndsWith("a different Director must give the second approval.", await ErrorOf(sameAgain));
        Assert.Equal(HttpStatusCode.OK, second.StatusCode);
        var invoice = await Read(secondDirector, invoiceId);
        Assert.Equal("Approved", invoice.GetProperty("status").GetString());
        Assert.Equal("demo.director", invoice.GetProperty("firstApprovedBy").GetString());
        Assert.Equal("demo.director2", invoice.GetProperty("decidedBy").GetString());
    }

    [Fact]
    public async Task Approve_InvoiceThatIsNotPending_Returns409AndUnknownInvoiceReturns404()
    {
        var director = await SignedInAs("demo.director");
        var invoiceId = await PendingInvoice(director, 100m);
        (await director.PostAsync($"/api/approvals/{invoiceId}/approve", null)).EnsureSuccessStatusCode();

        var again = await director.PostAsync($"/api/approvals/{invoiceId}/approve", null);
        var unknown = await director.PostAsync("/api/approvals/INV-404/approve", null);

        Assert.Equal(HttpStatusCode.Conflict, again.StatusCode);
        Assert.Equal($"Invoice {invoiceId} is Approved; only pending invoices can be decided.", await ErrorOf(again));
        Assert.Equal(HttpStatusCode.NotFound, unknown.StatusCode);
    }

    // FR-009: Admin keeps the right to reject that it had before the feature.
    [Fact]
    public async Task Reject_AsAdmin_IsStillAllowed()
    {
        var admin = await SignedInAs("demo.admin");
        var invoiceId = await PendingInvoice(admin, 750_000m);

        var response = await admin.PostAsJsonAsync($"/api/approvals/{invoiceId}/reject", new { reason = "Duplicate invoice" });

        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
        Assert.Equal("Rejected", (await Read(admin, invoiceId)).GetProperty("status").GetString());
    }

    [Fact]
    public async Task Approve_WithoutSigningIn_Returns401()
    {
        var anonymous = _factory.CreateClient();

        var response = await anonymous.PostAsync("/api/approvals/INV-1001/approve", null);

        Assert.Equal(HttpStatusCode.Unauthorized, response.StatusCode);
    }
}

using System.Globalization;
using System.Text.Json;
using InvoiceApp.Domain;
using Xunit;

namespace InvoiceApp.Tests;

public class ApprovalServiceTests
{
    // Role names and amounts are written out on purpose, not read from ApprovalLimits,
    // so a wrong constant in production code cannot hide behind the same constant in a test.
    private static readonly Approver Manager = new("demo.manager", "Manager");
    private static readonly Approver Director = new("demo.director", "Director");
    private static readonly Approver SecondDirector = new("demo.director2", "Director");

    private static Invoice InvoiceWith(string id, InvoiceStatus status, decimal amount = 100m) =>
        new() { Id = id, CustomerName = "Test School", Amount = amount, Status = status };

    private static Invoice PendingInvoice(decimal amount) => InvoiceWith("INV-1", InvoiceStatus.PendingApproval, amount);

    private static Invoice InvoiceWithFirstApproval(decimal amount, string firstApprover)
    {
        var invoice = PendingInvoice(amount);
        invoice.FirstApprovedBy = firstApprover;
        invoice.FirstApprovedAt = new DateTime(2026, 10, 20, 9, 0, 0, DateTimeKind.Utc);
        return invoice;
    }

    private static ApprovalService ServiceFor(params Invoice[] invoices) =>
        new(new FakeInvoiceRepository(invoices));

    /// <summary>Every public property of the invoice, so a field added later is covered automatically.</summary>
    private static string Snapshot(Invoice invoice) => JsonSerializer.Serialize(invoice);

    /// <summary>AL-5: a refused approval gives a reason and leaves the invoice and the repository untouched.</summary>
    private static ApprovalDeniedException AssertDeniedAndUnchanged(Invoice invoice, Approver approver)
    {
        var repository = new FakeInvoiceRepository(invoice);
        var service = new ApprovalService(repository);
        var before = Snapshot(invoice);

        var denial = Assert.Throws<ApprovalDeniedException>(() => service.Approve(invoice.Id, approver));

        Assert.Equal(before, Snapshot(invoice));
        Assert.Equal(0, repository.UpdateCount);
        return denial;
    }

    [Fact]
    public void Submit_MovesDraftToPendingApproval()
    {
        var invoice = InvoiceWith("INV-1", InvoiceStatus.Draft);

        var repository = new FakeInvoiceRepository(invoice);

        var result = new ApprovalService(repository).Submit("INV-1");

        Assert.Equal(InvoiceStatus.PendingApproval, result.Status);
        Assert.Equal(new[] { "INV-1" }, repository.UpdatedIds);
    }

    [Fact]
    public void Submit_RejectsInvoiceThatIsNotADraftWithItsStatusAndChangesNothing()
    {
        var invoice = InvoiceWith("INV-1", InvoiceStatus.Approved);
        var repository = new FakeInvoiceRepository(invoice);
        var before = Snapshot(invoice);

        var error = Assert.Throws<InvalidOperationException>(() => new ApprovalService(repository).Submit("INV-1"));

        Assert.Equal("Invoice INV-1 is Approved; only drafts can be submitted.", error.Message);
        Assert.Equal(before, Snapshot(invoice));
        Assert.Equal(0, repository.UpdateCount);
    }

    [Fact]
    public void Approve_SetsStatusApproverAndTimestamp()
    {
        var service = ServiceFor(InvoiceWith("INV-1", InvoiceStatus.PendingApproval));

        var before = DateTime.UtcNow;

        var result = service.Approve("INV-1", Manager);

        Assert.Equal(InvoiceStatus.Approved, result.Status);
        Assert.Equal("demo.manager", result.DecidedBy);
        Assert.Equal(DateTimeKind.Utc, result.DecidedAt!.Value.Kind);
        Assert.InRange(result.DecidedAt.Value, before, DateTime.UtcNow);
    }

    // FR-009: "only pending invoices" still answers before any limit (409, not 403), with the status in the reason.
    // The amount is above the Manager limit on purpose, so swapping the two checks would change the answer.
    [Theory]
    [InlineData(InvoiceStatus.Draft)]
    [InlineData(InvoiceStatus.Approved)]
    [InlineData(InvoiceStatus.Rejected)]
    public void Approve_InvoiceThatIsNotPending_IsRefusedWithItsStatusBeforeAnyLimitAndChangesNothing(InvoiceStatus status)
    {
        var invoice = InvoiceWith("INV-1", status, amount: 600_000m);
        invoice.DecidedBy = status == InvoiceStatus.Draft ? null : "demo.director";
        var repository = new FakeInvoiceRepository(invoice);
        var before = Snapshot(invoice);

        var error = Assert.Throws<InvalidOperationException>(() => new ApprovalService(repository).Approve("INV-1", Manager));

        Assert.IsNotType<ApprovalDeniedException>(error);
        Assert.Equal($"Invoice INV-1 is {status}; only pending invoices can be decided.", error.Message);
        Assert.Equal(before, Snapshot(invoice));
        Assert.Equal(0, repository.UpdateCount);
    }

    [Fact]
    public void Approve_ThrowsWhenInvoiceDoesNotExist()
    {
        var service = ServiceFor();

        var error = Assert.Throws<KeyNotFoundException>(() => service.Approve("INV-404", Manager));

        Assert.Equal("Invoice INV-404 was not found.", error.Message);
    }

    [Fact]
    [Trait("Rule", "AL-1")]
    public void Approve_ManagerAtExactlyFiftyThousand_ApprovesAndSavesOnlyThatInvoice()
    {
        var invoice = PendingInvoice(50_000.00m);
        var otherInvoice = InvoiceWith("INV-2", InvoiceStatus.PendingApproval, 50_000.00m);
        var otherBefore = Snapshot(otherInvoice);
        var repository = new FakeInvoiceRepository(invoice, otherInvoice);

        var result = new ApprovalService(repository).Approve("INV-1", Manager);

        Assert.Equal(InvoiceStatus.Approved, result.Status);
        Assert.Equal("demo.manager", result.DecidedBy);
        Assert.Null(result.DecisionNote);
        Assert.Equal(new[] { "INV-1" }, repository.UpdatedIds);
        Assert.Equal(otherBefore, Snapshot(otherInvoice));
    }

    [Fact]
    [Trait("Rule", "AL-1")]
    [Trait("Rule", "AL-5")]
    public void Approve_ManagerOneCentAboveFiftyThousand_IsDeniedWithReasonAndChangesNothing()
    {
        var denial = AssertDeniedAndUnchanged(PendingInvoice(50_000.01m), Manager);

        Assert.Equal(
            "Invoice INV-1 is 50,000.01, which is above the Manager limit of 50,000.00. A Director must approve it.",
            denial.Message);
    }

    [Fact]
    [Trait("Rule", "AL-1")]
    [Trait("Rule", "AL-2")]
    public void Approve_AmountBetweenTheLimits_IsDeniedForManagerAndApprovedByDirector()
    {
        var invoice = PendingInvoice(120_000m);

        var denial = AssertDeniedAndUnchanged(invoice, Manager);
        Assert.Equal(
            "Invoice INV-1 is 120,000.00, which is above the Manager limit of 50,000.00. A Director must approve it.",
            denial.Message);

        var result = ServiceFor(invoice).Approve("INV-1", Director);

        Assert.Equal(InvoiceStatus.Approved, result.Status);
        Assert.Equal("demo.director", result.DecidedBy);
    }

    [Fact]
    [Trait("Rule", "AL-1")]
    [Trait("Rule", "AL-5")]
    public void Approve_ManagerAtExactlyFiveHundredThousand_IsDeniedAndChangesNothing()
    {
        var denial = AssertDeniedAndUnchanged(PendingInvoice(500_000.00m), Manager);

        Assert.Equal(
            "Invoice INV-1 is 500,000.00, which is above the Manager limit of 50,000.00. A Director must approve it.",
            denial.Message);
    }

    // AGENTS.md: money in reasons uses the invariant culture, whatever the server's culture is.
    [Fact]
    [Trait("Rule", "AL-5")]
    public void Approve_DenialReason_FormatsMoneyTheSameUnderAnyServerCulture()
    {
        var originalCulture = CultureInfo.CurrentCulture;
        try
        {
            CultureInfo.CurrentCulture = new CultureInfo("de-DE");

            var denial = AssertDeniedAndUnchanged(PendingInvoice(120_000.50m), Manager);

            Assert.Contains("is 120,000.50, which is above the Manager limit of 50,000.00", denial.Message);
        }
        finally
        {
            CultureInfo.CurrentCulture = originalCulture;
        }
    }

    [Fact]
    [Trait("Rule", "AL-2")]
    public void Approve_DirectorAtExactlyFiveHundredThousand_ApprovesAlone()
    {
        var invoice = PendingInvoice(500_000.00m);
        var repository = new FakeInvoiceRepository(invoice);

        var result = new ApprovalService(repository).Approve("INV-1", Director);

        Assert.Equal(InvoiceStatus.Approved, result.Status);
        Assert.Equal("demo.director", result.DecidedBy);
        Assert.Equal(1, repository.UpdateCount);
    }

    [Theory]
    [Trait("Rule", "AL-6")]
    [Trait("Rule", "AL-5")]
    [InlineData("Admin")]
    [InlineData("Approver")]
    [InlineData("manager")]
    [InlineData("Manager ")]
    [InlineData("")]
    [InlineData(null)]
    public void Approve_RoleWithoutApprovalLimit_IsDeniedWithReasonAndChangesNothing(string? role)
    {
        var denial = AssertDeniedAndUnchanged(PendingInvoice(100m), new Approver("someone", role!));

        Assert.Equal(
            $"someone has role '{role}', which cannot approve invoices. A Manager or Director must approve it.",
            denial.Message);
    }

    // ---- Above 500,000.00: two different people, the second a Director (AL-3, AL-4) ----

    [Fact]
    [Trait("Rule", "AL-3")]
    public void Approve_DirectorFirstAboveFiveHundredThousand_RecordsFirstApprovalAndStaysPending()
    {
        var invoice = PendingInvoice(750_000m);
        var repository = new FakeInvoiceRepository(invoice);
        var before = DateTime.UtcNow;

        var result = new ApprovalService(repository).Approve("INV-1", Director);

        Assert.Equal(InvoiceStatus.PendingApproval, result.Status);
        Assert.Equal("demo.director", result.FirstApprovedBy);
        Assert.Equal(DateTimeKind.Utc, result.FirstApprovedAt!.Value.Kind);
        Assert.InRange(result.FirstApprovedAt.Value, before, DateTime.UtcNow);
        Assert.Null(result.DecidedBy);
        Assert.Null(result.DecidedAt);
        Assert.Null(result.DecisionNote);
        Assert.Equal(new[] { "INV-1" }, repository.UpdatedIds);
    }

    [Fact]
    [Trait("Rule", "AL-3")]
    public void Approve_DifferentDirectorSecond_ApprovesAndKeepsTheFirstApproval()
    {
        var invoice = PendingInvoice(750_000m);
        var repository = new FakeInvoiceRepository(invoice);
        var service = new ApprovalService(repository);
        var firstApprovedAt = service.Approve("INV-1", Director).FirstApprovedAt;

        var result = service.Approve("INV-1", SecondDirector);

        Assert.Equal(InvoiceStatus.Approved, result.Status);
        Assert.Equal("demo.director2", result.DecidedBy);
        Assert.NotNull(result.DecidedAt);
        Assert.Equal("demo.director", result.FirstApprovedBy);
        Assert.Equal(firstApprovedAt, result.FirstApprovedAt);
        Assert.Equal(2, repository.UpdateCount);
    }

    // AL-3: the first approver may be a Manager, even though a Manager cannot give a final approval above 50,000.00.
    [Fact]
    [Trait("Rule", "AL-1")]
